import pymupdf
doc = pymupdf.open("x962-11-17-97.pdf")
print("pages", doc.page_count, doc.metadata)
for i in range(doc.page_count):
    t = doc[i].get_text("text")
    for key in ["m = 176","m = 208","m = 272","m = 304","m = 368","H.4.","Weil Theorem","H.4. 7","H.4. 9"]:
        if key in t:
            print(i, repr(key))
    imgs = doc[i].get_images()
    if 85 <= i <= 95: print(i, "images", [(x[0], x[2], x[3]) for x in imgs])

